export CLAUDE_PROJECT_DIR="/private/tmp/claude-501/pr86-ci-live/lt/runs/sysspec123/fx" && cd -- "$CLAUDE_PROJECT_DIR" && [ "$(pwd -P)" = "$CLAUDE_PROJECT_DIR" ] && PLUGIN_ROOT="$CLAUDE_PROJECT_DIR/plugins/system-spec-harness" && python3 -c "
import json;s=json.load(open('system-spec/spec-state.json'))
print('schema',s.get('schema_version'),'keys',list(s.keys()))
print('hp',s.get('hearing_progress'))
m=s.get('matrix',{});
import collections;c=collections.Counter(v.get('state') for cat in m.values() for v in (cat.values() if isinstance(cat,dict) else []))
print(c); print('targets',[t.get('target_id') for t in s.get('targets',[])]); print('decisions',[ (d.get('id'),d.get('status')) for d in s.get('decisions',[])])
print('foundation confirmed',s.get('requirements_foundation',{}).get('confirmed'))
print('kc',[(k.get('id'),k.get('status')) for k in s.get('knowledge_candidates',[])])
"; python3 -B "$PLUGIN_ROOT/scripts/validate-coverage-matrix.py" --matrix system-spec/spec-state.json; echo loop=$?; python3 -B "$PLUGIN_ROOT/scripts/validate-coverage-matrix.py" --matrix system-spec/spec-state.json --require-complete --require-basis --require-foundation; echo out1=$?; python3 -B "$PLUGIN_ROOT/scripts/validate-design-knowledge-refs.py" --matrix "$CLAUDE_PROJECT_DIR/system-spec/spec-state.json" --repo-root "$CLAUDE_PROJECT_DIR"; echo dkr=$?; python3 -B "$PLUGIN_ROOT/scripts/validate-knowledge-graph.py" --profile required-info --input "$PLUGIN_ROOT/skills/run-system-spec-elicit/references/required-info-catalog.json" --state "$CLAUDE_PROJECT_DIR/system-spec/spec-state.json" > $TMPDIR/ri.json; echo ri=$?; python3 -c "import json,sys;d=json.load(open(sys.argv[1]));cc=d.get('coverage_certificate',{});print('ungrounded',cc.get('ungrounded_blocking_items'));print('order',d.get('collection_order'))" $TMPDIR/ri.json

